const canvas=document.querySelector('#world');
const ctx=canvas.getContext('2d');
let seed=42;
function hash(x,y){const n=Math.sin(x*127.1+y*311.7+seed)*43758.5453;return n-Math.floor(n)}
function noise(x,y){const ix=Math.floor(x),iy=Math.floor(y),fx=x-ix,fy=y-iy;const u=fx*fx*(3-2*fx),v=fy*fy*(3-2*fy);return (hash(ix,iy)*(1-u)+hash(ix+1,iy)*u)*(1-v)+(hash(ix,iy+1)*(1-u)+hash(ix+1,iy+1)*u)*v}
function polygon(points,color){ctx.fillStyle=color;ctx.beginPath();points.forEach(([x,y],i)=>i?ctx.lineTo(x,y):ctx.moveTo(x,y));ctx.closePath();ctx.fill()}
function block(x,y,z,top,left,right,size=1){const w=18*size,h=9*size,d=13*size;const px=640+(x-y)*18,py=45+(x+y)*9-z*13;polygon([[px,py],[px+w,py+h],[px,py+2*h],[px-w,py+h]],top);polygon([[px-w,py+h],[px,py+2*h],[px,py+2*h+d],[px-w,py+h+d]],left);polygon([[px,py+2*h],[px+w,py+h],[px+w,py+h+d],[px,py+2*h+d]],right)}
function render(){const rect=canvas.getBoundingClientRect();canvas.width=Math.round(rect.width*devicePixelRatio);canvas.height=Math.round(rect.height*devicePixelRatio);ctx.setTransform(canvas.width/1280,0,0,canvas.height/500,0,0);const sky=ctx.createLinearGradient(0,0,0,500);sky.addColorStop(0,'#192344');sky.addColorStop(.6,'#233e69');sky.addColorStop(1,'#1a4e8b');ctx.fillStyle=sky;ctx.fillRect(0,0,1280,500);ctx.fillStyle='#e4efff';ctx.fillRect(935,47,66,66);ctx.fillStyle='#b6cff230';[[100,60,160,16],[240,76,100,12],[650,30,140,10],[1040,130,190,12]].forEach(v=>ctx.fillRect(...v));for(let sum=-16;sum<95;sum++){for(let x=-30;x<62;x++){const y=sum-x;if(y< -18||y>62)continue;const n=noise(x*.095,y*.095)*.72+noise(x*.23,y*.23)*.28;let height=Math.floor((n-.43)*28);if(height<=0){if(hash(x*3,y*3)>.87){const px=640+(x-y)*18,py=45+(x+y)*9;ctx.fillStyle='#79bffb55';ctx.fillRect(px,py,14,2)}continue}height=Math.min(height,13);for(let z=0;z<height;z++)block(x,y,z,z===height-1?(height>10?'#c7d1df':height<2?'#bdab7c':['#69a13e','#588b32','#75b347'][Math.floor(hash(x,y)*3)]):'#73665a',z===height-1?'#4c7c32':'#756557',z===height-1?'#3b6428':'#4b4546');if(height>2&&height<10&&hash(x+8,y+8)>.87){block(x,y,height,'#817357','#675e46','#4a4c39',.42);for(let t=0;t<3;t++)block(x,y,height+.5+t*.65,['#326b32','#3e803b','#539741'][t],'#24522d','#1a3a26',1.1-t*.23)}if(height>2&&hash(x+99,y)>.985){block(x,y,height,'#d2c8a6','#a39274','#817761',.65)}}}const haze=ctx.createLinearGradient(0,0,0,500);haze.addColorStop(0,'#33467522');haze.addColorStop(.4,'#33467500');haze.addColorStop(1,'#04091644');ctx.fillStyle=haze;ctx.fillRect(0,0,1280,500)}
let resizeTimer;window.addEventListener('resize',()=>{clearTimeout(resizeTimer);resizeTimer=setTimeout(render,100)});render();
document.querySelector('#new-world').addEventListener('click',()=>{seed+=17;render()});
const demos={vanilla:['Retour à l’essentiel.','Minecraft Java · Vanilla','linear-gradient(145deg,#697f50,#354a3d)'],fabric:['Un monde de possibles.','Minecraft Java · Fabric','linear-gradient(145deg,#647e89,#314b54)'],forge:['Vois les choses en grand.','Minecraft Java · Forge','linear-gradient(145deg,#9c7752,#514335)']};
document.querySelectorAll('[data-demo]').forEach(button=>{button.setAttribute('aria-pressed',String(button.classList.contains('selected')));button.addEventListener('click',()=>{document.querySelectorAll('[data-demo]').forEach(b=>{b.classList.remove('selected');b.setAttribute('aria-pressed','false')});button.classList.add('selected');button.setAttribute('aria-pressed','true');const [title,subtitle,background]=demos[button.dataset.demo];document.querySelector('#demo-title').textContent=title;document.querySelector('#demo-subtitle').textContent=subtitle;document.querySelector('.game-banner').style.background=background})});

